'use strict';
const attendanceNames={unmarked:'Não marcado',present:'Presente',absent:'Faltou',justified:'Falta justificada'};
const classUnits={amavale:'Amavale',valparaiso:'Valparaíso','vale-do-carangola':'Vale do Carangola'};
let classSelected='';
function todayBR(){const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));return `${p.year}-${p.month}-${p.day}`}
async function classList(){const {classes}=await api('/classes?unit='+$('class-unit').value);$('class-list').replaceChildren();for(const c of classes){const b=el('button',`${c.day} · ${c.time} · ${c.label}`,{class:'secondary registration-row'});b.addEventListener('click',action(()=>classDetail(c.id)));$('class-list').append(b)}if(!classes.length)$('class-list').append(el('p','Nenhuma aula cadastrada neste núcleo.'))}
async function classDetail(id){classSelected=id;const {lesson,students:rows}=await api('/classes/'+id+'/attendance'),box=$('class-detail');box.hidden=false;box.replaceChildren(el('h3',`${lesson.label} · ${classUnits[lesson.unit]} · ${lesson.day} ${lesson.time}`),el('p','Marque cada aluno individualmente. Não marcado não conta como falta. As justificativas são administrativas; não informe diagnósticos ou detalhes de saúde.'));
 const totals=Object.fromEntries(Object.keys(attendanceNames).map(k=>[k,rows.filter(r=>r.status===k).length]));box.append(el('p',Object.keys(attendanceNames).map(k=>attendanceNames[k]+': '+totals[k]).join(' · ')));
 const form=el('form');for(const r of rows){const line=el('div',undefined,{class:'attendance-row'}),label=el('label',r.name+' · '+r.id,{for:'attendance-'+r.id}),select=el('select',undefined,{id:'attendance-'+r.id,name:r.id});for(const [v,t]of Object.entries(attendanceNames))select.append(el('option',t,{value:v}));select.value=r.status;line.append(label,select);form.append(line)}
 if(rows.length){form.append(el('button','Salvar chamada'));form.addEventListener('submit',action(async()=>{const values=Object.fromEntries(new FormData(form)),changed=rows.filter(r=>values[r.id]!==r.status).map(r=>({id:r.id,status:values[r.id],version:r.version}));if(!changed.length){notice('Nenhuma marcação alterada.');return}const p=await api('/classes/'+id+'/attendance',{method:'POST',data:{rows:changed}});await classDetail(id);notice(p.message)}));box.append(form)}else box.append(el('p','Nenhum aluno aprovado neste núcleo.'));
}
function setupAttendance(){if($('attendance-area'))return;const area=el('section',undefined,{id:'attendance-area'});$('team-area').before(area);area.append(el('h2','Aulas e presença'),el('p','Cadastre a aula, abra a lista dos alunos e registre a chamada. Apenas administração e secretaria podem alterar presenças.'));
 const form=el('form',undefined,{id:'class-form'});field(form,'Núcleo da aula','unit','amavale',{options:classUnits}).id='class-unit';field(form,'Data da aula','day',todayBR(),{type:'date'}).required=true;field(form,'Horário','time','18:00',{type:'time'}).required=true;field(form,'Nome da aula','label','Jiu-Jitsu').required=true;form.append(el('button','Cadastrar aula'));area.append(form,el('div',undefined,{id:'class-list'}),el('section',undefined,{id:'class-detail',hidden:''}));
 $('class-unit').addEventListener('change',action(async()=>{$('class-detail').hidden=true;await classList()}));form.addEventListener('submit',action(async()=>{const p=await api('/classes',{method:'POST',data:Object.fromEntries(new FormData(form))});await classList();await classDetail(p.lesson.id);notice('Aula cadastrada. A presença deve ser registrada após a conferência da chamada.')}));
 const exportForm=el('form');exportForm.append(el('h3','Exportar presenças CSV'));field(exportForm,'De','from',todayBR().slice(0,7)+'-01',{type:'date'}).required=true;field(exportForm,'Até','to',todayBR(),{type:'date'}).required=true;exportForm.append(el('button','Baixar presenças CSV'));exportForm.addEventListener('submit',action(async()=>{const values=Object.fromEntries(new FormData(exportForm)),query=new URLSearchParams({...values,unit:$('class-unit').value});download(await api('/attendance.csv?'+query,{blob:true}),'presencas.csv')}));area.append(exportForm);$('admin-nav').append(el('a','Presenças',{href:'#attendance-area'}));
}
document.addEventListener('portal:loaded',action(async()=>{if(['admin','secretary'].includes(me.role)){setupAttendance();$('attendance-area').hidden=false;await classList()}else if($('attendance-area'))$('attendance-area').hidden=true}));
document.addEventListener('portal:logout',()=>{if($('attendance-area')){$('attendance-area').hidden=true;$('class-detail').replaceChildren();$('class-list').replaceChildren()}classSelected=''});

async function showPrivateAppointment(id,box){
 const {student:s,contact}=await api('/students/'+id+'/appointment');box.replaceChildren(el('h3','Solicitar atendimento'),el('p',`${s.name} · ${s.age} anos · ${s.id}`),el('p','Os dados do aluno vêm do cadastro aprovado. Confira o contato e escolha a preferência. A secretaria confirmará o atendimento por WhatsApp.'));
 const form=el('form');field(form,'Nome do solicitante','contactName',contact.guardian_name).required=true;field(form,'WhatsApp com DDD','phone',contact.guardian_phone,{type:'tel'}).required=true;
 field(form,'Atendimento','service','Psicologia',{options:{Psicologia:'Psicologia','Assistência social':'Assistência social'}});const day=field(form,'Data desejada','date','',{type:'date',min:todayBR()});day.required=true;field(form,'Horário desejado (Brasília)','time','',{type:'time'}).required=true;
 const label=el('label',undefined,{class:'check-label'}),consent=el('input',undefined,{type:'checkbox'});consent.required=true;label.append(consent,document.createTextNode('Estou ciente de que a solicitação aguarda confirmação da secretaria por WhatsApp.'));form.append(label,el('button','Enviar solicitação'));
 let requestId=crypto.randomUUID(),sent=false;form.addEventListener('input',()=>{if(!sent)requestId=crypto.randomUUID()});
 form.addEventListener('submit',action(async()=>{if(sent)return;const v=Object.fromEntries(new FormData(form));v.weekday=new Date(v.date+'T12:00:00Z').getUTCDay();v.consent=consent.checked;v.requestId=requestId;const p=await api('/students/'+id+'/appointment',{method:'POST',data:v});sent=true;form.replaceChildren(el('p',p.message+' Protocolo: '+p.protocol));notice(p.message)}));box.append(form);
}
